def is_valid_amount(v):
    if isinstance(v, bool):
        return False
    if not isinstance(v, int):
        return False
    return v > 0

billable = []
rejected = []
rows = input if isinstance(input, list) else []
for row in rows:
    if not isinstance(row, dict):
        rejected.append({"row": row, "reason": "not_an_object"})
        continue
    cid = row.get("customer_id")
    amt = row.get("amount_cents")
    if not cid:
        rejected.append({"row": row, "reason": "missing_customer_id"})
        continue
    if amt is None:
        rejected.append({"row": row, "reason": "missing_amount"})
        continue
    if not is_valid_amount(amt):
        rejected.append({"row": row, "reason": "invalid_amount"})
        continue
    billable.append({"customer_id": cid, "amount_cents": amt})
output = {"billable": billable, "rejected": rejected}

ps = input.get("plan_summary_output") or {}
proceed = bool(ps.get("proceed"))
intended = ps.get("billable_count") or 0
charge_out = input.get("charge_output") or {}
raw_items = charge_out.get("items")
if isinstance(raw_items, list):
    items = raw_items
elif charge_out.get("id"):
    items = [charge_out]
else:
    items = []
landed_items = [it for it in items if it.get("id")]
landed = len(landed_items)
statuses = sorted(set(str(it.get("status")) for it in landed_items))
output = {
    "intended": intended,
    "landed": landed,
    "difference": intended - landed,
    "blocked_by_cap": (not proceed) and intended > 0,
    "total_planned_cents": ps.get("total_cents") or 0,
    "statuses_seen": statuses,
}
